if(mode==='salute'){
   // Front view: index0 is his anatomical right. Release the held hand before raising it.
   const release=smooth(t/.35),raise=smooth((t-.35)/.75),held=son.hands[0];
   mother.hands[1]=[mother.hands[1][0]+(84-mother.hands[1][0])*release,mother.hands[1][1]+(-166-mother.hands[1][1])*release];
   const rest:Point=[held[0]+(-84-held[0])*release,held[1]+(-166-held[1])*release];
   son.hands[0]=[rest[0]+(-166-rest[0])*raise,rest[1]+(-521-rest[1])*raise];
   son.hands[1]=[84,-166];
   son.elbows=[[-128-57*raise,-244-101*raise],[125,-244]];
  }
